// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);

        GasGuzzler guzzler = new GasGuzzler();

        address owner = c.owner();
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        bool ok = true;
        try c.sendMoney(address(guzzler), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = owner.balance;

        assertTrue(ok && balanceAfter == balanceBefore - amount);
    }
}

contract GasGuzzler {
    receive() external payable {
        uint256 x;
        for (uint256 i = 0; i < 50; i++) {
            x = i * 2;
        }
    }
}
